// ---- Build Prompt (Versuch 1) ----
const payload = ($('Webhook').first().json.body) || $('Webhook').first().json || {};

const difficulty = ["easy","medium","hard"].includes(payload.difficulty) ? payload.difficulty : "medium";
const SUBTLETY = {
  easy:   "Die Halluzinationen duerfen relativ offensichtlich sein (klar erfundene Institutionen/Gesetze).",
  medium: "Die Halluzinationen sollen plausibel klingen und leichtes Nachdenken erfordern.",
  hard:   "Die Halluzinationen sollen sehr subtil sein (leicht falsche Zahlen, fast-korrekte Paragraphen)."
};

const learningGoal = payload.learningGoal === "other"
  ? (payload.learningGoalCustom || "Allgemeines Finance-Thema")
  : (payload.learningGoal || "Allgemeines Finance-Thema");
const techLabel   = payload.technologyLabel || payload.technologyCustom || "KI-Technologie";
const techContext = payload.technologyWhatsNew ? ("Kontext zur Technologie: " + payload.technologyWhatsNew) : "";

const systemPrompt = `Du bist Spiel-Generator fuer "Halluzinationen erkennen"-Challenges der Lufthansa Finance Training Academy. Zielgruppe: eine Controllerin ohne KI-Vorwissen. Sie lernt, erfundene Zahlen, Gesetze, Paragraphen, Institutionen und Fristen in KI-Antworten zu erkennen.

Gib AUSSCHLIESSLICH valides JSON zurueck, KEINE Markdown-Code-Bloecke, exakt in diesem FLACHEN Format:
{
 "title": "<kurzer deutscher Titel>",
 "topic": "<Themenschlagwort, 1-3 Woerter>",
 "situation": "<deutsche Arbeitssituation, 1-2 Saetze: jemand fragt die KI etwas>",
 "promptOptions": [ 5 Objekte ],
 "sentences": [ 20 bis 30 Objekte ]
}

promptOptions: GENAU 5 Eintraege. Jeder Eintrag:
 { "id": 1..5, "text": "<Prompt-Formulierung>", "approach": "<einer der Werte>", "quality": <0-100>, "isRecommended": <bool>, "feedback": "<2-3 Saetze warum gut/schlecht>" }
- approach MUSS jeden dieser Werte GENAU EINMAL verwenden: "vage", "kontext", "rolle", "quellen", "suggestiv".
- GENAU EIN Eintrag hat isRecommended:true, und zwar der mit der HOECHSTEN quality.
- quality: vage & suggestiv niedrig (<40), kontext & rolle mittel, quellen am hoechsten.
- feedback nie leer. id luueckenlos 1..5.

sentences: 20 bis 30 Saetze, die zusammen die (fiktive) KI-Antwort auf den EMPFOHLENEN Prompt bilden. Jeder Eintrag:
 { "id": 1..N, "text": "<ein Satz>", "isHallucination": <bool>, "explanation": "<warum (nicht) halluziniert>" }
- GENAU 3 bis 6 Saetze haben isHallucination:true.
- Halluzinationen = erfundene Zahlen, Gesetze, Paragraphen, Institutionen oder Fristen, die plausibel klingen aber faktisch falsch/nicht existent sind.
- Nicht-Halluzinationen muessen sachlich korrekt sein.
- explanation nie leer. id luueckenlos 1..N.

HARTE REGELN:
- Antworte nur mit dem JSON-Objekt, nichts davor/danach.
- Zahlen als echte JSON-Zahlen, nicht als Strings.
- ${SUBTLETY[difficulty]}

Schwierigkeit: ${difficulty}. Lernziel: ${learningGoal}. Technologie-Bezug: ${techLabel}. ${techContext}`;

const userPrompt = `Erzeuge jetzt eine "Halluzinationen erkennen"-Challenge zum Lernziel "${learningGoal}" mit Bezug zur Technologie "${techLabel}", Schwierigkeit "${difficulty}". Gib ausschliesslich das JSON im vorgegebenen Format zurueck.`;

const llm_body = {
  model: "OpenAI GPT OSS 120b KI:Inferenz.nrw",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user",   content: userPrompt }
  ],
  temperature: 0.7,
  max_tokens: 4000
};

return [{ json: { llm_body, attempt: 1, difficulty, payload } }];

// ---- Process & Validate (Versuch 1) ----
const resp = $json;
const bp = $('Build Prompt').first().json;
const payload = bp.payload;
const attempt = 1;

function fail(errors, raw) {
  return [{ json: { valid: false, errors, game_json: null, payload,
    meta: { attempt, model: bp.llm_body.model }, raw } }];
}

let content = "";
try { content = resp.choices[0].message.content; }
catch (e) { return fail(["LLM-Antwort ohne choices/content"], resp); }
const usage = resp.usage || null;

let data;
try {
  const cleaned = String(content).replace(/```json/gi, "").replace(/```/g, "").trim();
  const s = cleaned.indexOf("{"), e = cleaned.lastIndexOf("}");
  data = JSON.parse(s !== -1 && e !== -1 ? cleaned.slice(s, e + 1) : cleaned);
} catch (e) { return fail(["LLM-Ausgabe ist kein valides JSON (evtl. abgeschnitten -> max_tokens): " + e.message], content); }

function contiguousFrom1(ids) {
  if (!ids.length) return false;
  const sorted = ids.map(Number).sort((a,b)=>a-b);
  return sorted.every((v,i)=>v===i+1);
}

const errors = [];
const APPROACHES = ["vage","kontext","rolle","quellen","suggestiv"];

if (typeof data.title !== "string" || !data.title.trim()) errors.push('Feld "title" fehlt/leer');
if (typeof data.situation !== "string" || !data.situation.trim()) errors.push('Feld "situation" fehlt/leer');

const opts = Array.isArray(data.promptOptions) ? data.promptOptions : [];
if (opts.length !== 5) errors.push("promptOptions: erwartet 5, erhalten " + opts.length);
APPROACHES.forEach(a => {
  const c = opts.filter(o => o && o.approach === a).length;
  if (c !== 1) errors.push('approach "' + a + '": erwartet genau 1, erhalten ' + c);
});
const rec = opts.filter(o => o && o.isRecommended === true);
if (rec.length !== 1) {
  errors.push("isRecommended: erwartet genau 1 (true), erhalten " + rec.length);
} else {
  const maxQ = Math.max.apply(null, opts.map(o => Number(o && o.quality) || 0));
  if ((Number(rec[0].quality) || 0) !== maxQ) errors.push("isRecommended nicht auf hoechster quality (" + rec[0].quality + " vs max " + maxQ + ")");
}
opts.forEach((o,i) => {
  if (!o || typeof o.quality !== "number") errors.push("promptOption #" + (i+1) + ": quality keine Zahl");
  if (!o || !o.feedback || !String(o.feedback).trim()) errors.push("promptOption #" + (i+1) + ": feedback leer");
  if (!o || !o.text || !String(o.text).trim()) errors.push("promptOption #" + (i+1) + ": text leer");
});
if (!contiguousFrom1(opts.map(o => o && o.id))) errors.push("promptOptions: ids nicht lueckenlos ab 1");

const sents = Array.isArray(data.sentences) ? data.sentences : [];
if (sents.length < 20 || sents.length > 30) errors.push("sentences: erwartet 20-30, erhalten " + sents.length);
const hallu = sents.filter(s => s && s.isHallucination === true).length;
if (hallu < 3 || hallu > 6) errors.push("Halluzinationen: erwartet 3-6, erhalten " + hallu);
sents.forEach((s,i) => {
  if (!s || typeof s.isHallucination !== "boolean") errors.push("Satz #" + (i+1) + ": isHallucination kein boolean");
  if (!s || !s.text || !String(s.text).trim()) errors.push("Satz #" + (i+1) + ": text leer");
  if (!s || !s.explanation || !String(s.explanation).trim()) errors.push("Satz #" + (i+1) + ": explanation leer");
});
if (!contiguousFrom1(sents.map(s => s && s.id))) errors.push("sentences: ids nicht lueckenlos ab 1");

if (errors.length) return fail(errors, content);

// --- assemble game_json (Code baut die Huelle, LLM lieferte flach) ---
const game_json = {
  format: "hallucination_spotter_v2",
  halluRound: {
    situation: String(data.situation).trim(),
    promptOptions: opts.map(o => ({
      id: Number(o.id), text: String(o.text).trim(), approach: String(o.approach),
      quality: Number(o.quality), isRecommended: o.isRecommended === true, feedback: String(o.feedback).trim()
    })),
    answer: { sentences: sents.map(s => ({
      id: Number(s.id), text: String(s.text).trim(),
      isHallucination: s.isHallucination === true, explanation: String(s.explanation).trim()
    })) }
  }
};

return [{ json: { valid: true, errors: [], game_json, payload,
  llm_title: String(data.title).trim(),
  llm_topic: data.topic ? String(data.topic).trim() : null,
  meta: { attempt, model: bp.llm_body.model, tokens: usage, halluCount: hallu, sentenceCount: sents.length },
  raw: null } }];

// ---- Build Repair Prompt (Versuch 2) ----
const prev = $('Process & Validate 1').first().json;
const bp = $('Build Prompt').first().json;
const errors = prev.errors || [];
const rawPrev = prev.raw;

const repairSystem = bp.llm_body.messages[0].content;
const repairUser = "Dein vorheriger Versuch war UNGUELTIG. Zu behebende Fehler:\n- "
  + errors.join("\n- ")
  + "\n\nDein vorheriger (fehlerhafter) Output:\n" + JSON.stringify(rawPrev)
  + "\n\nKorrigiere GENAU diese Fehler und gib erneut AUSSCHLIESSLICH das valide JSON im vorgegebenen Format zurueck.";

const llm_body = {
  model: bp.llm_body.model,
  messages: [
    { role: "system", content: repairSystem },
    { role: "user",   content: repairUser }
  ],
  temperature: 0.2,
  max_tokens: 4000
};

return [{ json: { llm_body, attempt: 2, difficulty: bp.difficulty, payload: bp.payload } }];

